    values.oldValue     = '$69'
    values.currentValue = '$59'
    values.threeBottles = '$39'
    values.sixBottles   = '$29'
    values.imagePath    = '/assets/relaxv_price_USD.webp'
    values.combo3Img    = '/assets/US/3usd.webp'
    values.combo6Img    = '/assets/US/6usd.webp'
  }
})

